-- Additional work approval (WMS-009, WEB-025). Tables generated by prisma migrate diff, then
-- reviewed; checks and triggers are hand-written.

-- AlterTable
ALTER TABLE "workshop"."job_task" ADD COLUMN     "addition_id" UUID;

-- CreateTable
CREATE TABLE "workshop"."job_addition" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "company_id" UUID NOT NULL,
    "job_id" UUID NOT NULL,
    "seq" INTEGER NOT NULL,
    "finding" TEXT NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'proposed',
    "proposed_by" UUID NOT NULL,
    "proposed_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "authorized_by_name" TEXT,
    "authorized_via" TEXT,
    "decided_at" TIMESTAMPTZ(6),
    "decided_by" UUID,
    "close_reason" TEXT,

    CONSTRAINT "job_addition_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "workshop"."job_addition_item" (
    "addition_id" UUID NOT NULL,
    "line_no" INTEGER NOT NULL,
    "description" TEXT NOT NULL,
    "estimated_hours" DECIMAL(5,2) NOT NULL,

    CONSTRAINT "job_addition_item_pkey" PRIMARY KEY ("addition_id","line_no")
);

-- CreateIndex
CREATE UNIQUE INDEX "job_addition_job_id_seq_key" ON "workshop"."job_addition"("job_id", "seq");

-- AddForeignKey
ALTER TABLE "workshop"."job_task" ADD CONSTRAINT "job_task_addition_id_fkey" FOREIGN KEY ("addition_id") REFERENCES "workshop"."job_addition"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "workshop"."job_addition" ADD CONSTRAINT "job_addition_company_id_job_id_fkey" FOREIGN KEY ("company_id", "job_id") REFERENCES "workshop"."job_card"("company_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "workshop"."job_addition_item" ADD CONSTRAINT "job_addition_item_addition_id_fkey" FOREIGN KEY ("addition_id") REFERENCES "workshop"."job_addition"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- Hand-written rules -------------------------------------------------------

ALTER TABLE workshop.job_addition
  ADD CONSTRAINT job_addition_status_valid CHECK (status IN ('proposed', 'approved', 'declined', 'withdrawn')),
  ADD CONSTRAINT job_addition_seq_positive CHECK (seq > 0),
  ADD CONSTRAINT job_addition_approved_complete CHECK (
    status <> 'approved'
    OR (authorized_by_name IS NOT NULL AND authorized_via IN ('in_person', 'phone', 'written'))),
  ADD CONSTRAINT job_addition_closed_reason CHECK (status NOT IN ('declined', 'withdrawn') OR close_reason IS NOT NULL),
  ADD CONSTRAINT job_addition_decided CHECK ((status = 'proposed') = (decided_at IS NULL AND decided_by IS NULL));

-- One open proposal per job at a time: the customer decides one question at once.
CREATE UNIQUE INDEX job_addition_one_open ON workshop.job_addition (job_id) WHERE status = 'proposed';

ALTER TABLE workshop.job_addition_item
  ADD CONSTRAINT job_addition_item_hours_positive CHECK (estimated_hours > 0);

-- A decided proposal is a record: it never changes, and nothing is deleted.
CREATE OR REPLACE FUNCTION workshop.guard_job_addition() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' OR OLD.status <> 'proposed'
     OR NEW.id <> OLD.id OR NEW.job_id <> OLD.job_id OR NEW.company_id <> OLD.company_id
     OR NEW.seq <> OLD.seq OR NEW.finding <> OLD.finding OR NEW.proposed_by <> OLD.proposed_by
     OR NEW.proposed_at <> OLD.proposed_at THEN
    RAISE EXCEPTION 'job_addition_immutable' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER job_addition_guard BEFORE UPDATE OR DELETE ON workshop.job_addition
  FOR EACH ROW EXECUTE FUNCTION workshop.guard_job_addition();
CREATE TRIGGER job_addition_item_immutable BEFORE UPDATE OR DELETE ON workshop.job_addition_item
  FOR EACH ROW EXECUTE FUNCTION platform.forbid_mutation();

-- Items are only added while the proposal is open (in the same transaction as the proposal).
CREATE OR REPLACE FUNCTION workshop.guard_job_addition_item() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM workshop.job_addition a WHERE a.id = NEW.addition_id AND a.status = 'proposed') THEN
    RAISE EXCEPTION 'job_addition_item_closed' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER job_addition_item_open BEFORE INSERT ON workshop.job_addition_item
  FOR EACH ROW EXECUTE FUNCTION workshop.guard_job_addition_item();

-- Tasks join a job after authorisation only through approved additional work of the same job.
CREATE OR REPLACE FUNCTION workshop.guard_task_authorised() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  st text;
BEGIN
  SELECT status INTO st FROM workshop.job_card WHERE id = NEW.job_id;
  IF NEW.addition_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM workshop.job_addition a
                    WHERE a.id = NEW.addition_id AND a.job_id = NEW.job_id AND a.status = 'approved') THEN
      RAISE EXCEPTION 'job_task_addition_not_approved' USING ERRCODE = 'restrict_violation';
    END IF;
  ELSIF st IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION 'job_task_after_authorisation' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER job_task_authorised BEFORE INSERT ON workshop.job_task
  FOR EACH ROW EXECUTE FUNCTION workshop.guard_task_authorised();

-- Timeline and notifications.
ALTER TABLE workshop.job_event DROP CONSTRAINT job_event_kind_valid;
ALTER TABLE workshop.job_event ADD CONSTRAINT job_event_kind_valid CHECK (kind IN (
  'created', 'status', 'assignment', 'task_done', 'task_reopened', 'qc_pass', 'qc_fail', 'note', 'updated',
  'inspection', 'photo_added', 'photo_removed',
  'addition_proposed', 'addition_approved', 'addition_declined', 'addition_withdrawn'));

ALTER TABLE platform.notification DROP CONSTRAINT notification_kind_valid;
ALTER TABLE platform.notification ADD CONSTRAINT notification_kind_valid CHECK (kind IN (
  'journal_reversed', 'role_granted', 'role_revoked', 'role_changed', 'period_closed',
  'export_ready', 'export_failed', 'job_assigned', 'job_rework', 'job_ready',
  'job_addition_proposed', 'job_addition_approved', 'job_addition_declined'));
